package dev.recipeeditor.exporters;

import java.nio.file.Path;
import java.util.*;
import dev.recipeeditor.recipeengine.editor.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

final class CraftTweakerRecipeExporterTest {
    @TempDir Path root;
    @Test void correctCraftingManagerImportsAndNamespacePreservation()throws Exception {final var f=new ExportFixtures(root);final var plan=f.plan(List.of(f.create("crafttweaker:folder/new",f.raw)),ExportFormat.CRAFTTWEAKER);assertTrue(plan.valid(),plan.diagnostics().toString());final var zs=plan.files().values().iterator().next();assertTrue(zs.contains("import crafttweaker.api.data.MapData;"));assertTrue(zs.contains("<recipetype:minecraft:crafting>.addJsonRecipe(\"folder/new\""));assertTrue(zs.contains("as MapData"));assertFalse(f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.CRAFTTWEAKER).valid());}
    @Test void updateAndFullIdDeletionUseManagerMethods()throws Exception {final var f=new ExportFixtures(root);final var base=f.original("crafttweaker:base",f.raw);final var deleted=f.original("other:deleted",f.raw);final var c=List.of(f.change(base,RecipeChangeType.UPDATE,f.raw),f.change(deleted,RecipeChangeType.DELETE,""));final var ctx=f.context(c,List.of(base,deleted),ExportFormat.CRAFTTWEAKER,Map.of("crafttweaker","14.0.57"),List.of(),OverwritePolicy.OWNED_UNCHANGED);final var p=f.planner.plan(f.request(ctx));assertTrue(p.valid(),p.diagnostics().toString());final String zs=p.files().values().iterator().next();assertTrue(zs.indexOf("removeByName(\"crafttweaker:base\")")<zs.indexOf("addJsonRecipe(\"base\""));assertTrue(zs.contains("removeByName(\"other:deleted\")"));}
    @Test void smithingManagerAndFloatDataAreVersionSpecific()throws Exception {final var f=new ExportFixtures(root);final String smelt="{\"type\":\"minecraft:smelting\",\"ingredient\":{\"item\":\"minecraft:iron_ore\"},\"result\":\"minecraft:iron_ingot\",\"experience\":0.7}";final var p=f.plan(List.of(f.create("crafttweaker:smelt",smelt)),ExportFormat.CRAFTTWEAKER);assertTrue(p.valid(),p.diagnostics().toString());assertTrue(p.files().values().iterator().next().contains("<recipetype:minecraft:smelting>"));assertTrue(p.files().values().iterator().next().contains("(0.7 as float)"));DatapackRecipeExporterTest.types().filter(a->a.get()[0].toString().startsWith("smithing")).forEach(a->{final var plan=f.plan(List.of(f.create("crafttweaker:smith","{\"type\":\"minecraft:"+a.get()[0]+"\","+a.get()[1]+"}")),ExportFormat.CRAFTTWEAKER);assertTrue(plan.valid(),plan.diagnostics().toString());assertTrue(plan.files().values().iterator().next().contains("<recipetype:minecraft:smithing>"));});}
    @Test void unsupportedTypesAndMissingDependenciesAreRejected()throws Exception {final var f=new ExportFixtures(root);assertFalse(f.plan(List.of(f.create("crafttweaker:new","{\"type\":\"unknown:recipe\"}")),ExportFormat.CRAFTTWEAKER).valid());final var c=f.create("crafttweaker:new",f.raw);assertFalse(new CraftTweakerRecipeExporter().checkCapability(c,f.context(List.of(c),List.of(),ExportFormat.CRAFTTWEAKER,Map.of(),List.of(),OverwritePolicy.REFUSE)).supported());}
    @Test void zenDataEscapesStringsAndRejectsNullOrOversizedIntegers() {final var generator=new ZenScriptGenerator();assertTrue(generator.data("{\"group\":\"\\\"; evil(); //\\n\"}").contains("\\\"; evil(); //\\n"));assertThrows(IllegalArgumentException.class,()->generator.data("{\"x\":null}"));assertThrows(IllegalArgumentException.class,()->generator.data("{\"x\":9223372036854775807}"));}
}
